//! HTTP routes and handlers.

use std::sync::Arc;

use axum::body::Bytes;
use axum::extract::{DefaultBodyLimit, Path, RawQuery, State};
use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use axum::{Json, Router};
use serde_json::{Map, Value, json};

use crate::db::{ListFilter, Store};
use crate::model::{Note, NoteInput, ValidationError};

const MAX_BODY_BYTES: usize = 16 * 1024 * 1024;
const MAX_LIMIT: usize = 100;

type AppState = Arc<Store>;

pub fn router(store: Arc<Store>) -> Router {
    Router::new()
        .route("/health", get(health).fallback(method_not_allowed))
        .route(
            "/notes",
            get(list_notes).post(create_note).fallback(method_not_allowed),
        )
        .route(
            "/notes/{id}",
            get(get_note)
                .put(update_note)
                .delete(delete_note)
                .fallback(method_not_allowed),
        )
        .route("/stats", get(stats).fallback(method_not_allowed))
        .route("/tags", get(tags).fallback(method_not_allowed))
        .fallback(not_found)
        .layer(DefaultBodyLimit::max(MAX_BODY_BYTES))
        .with_state(store)
}

#[derive(Debug, thiserror::Error)]
pub enum ApiError {
    #[error(transparent)]
    BadRequest(#[from] ValidationError),
    #[error("{0}")]
    BadQuery(&'static str),
    #[error("not found")]
    NotFound,
    #[error("method not allowed")]
    MethodNotAllowed,
    #[error("internal error")]
    Internal(#[source] anyhow::Error),
}

impl From<rusqlite::Error> for ApiError {
    fn from(e: rusqlite::Error) -> Self {
        Self::Internal(e.into())
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let status = match &self {
            Self::BadRequest(_) | Self::BadQuery(_) => StatusCode::BAD_REQUEST,
            Self::NotFound => StatusCode::NOT_FOUND,
            Self::MethodNotAllowed => StatusCode::METHOD_NOT_ALLOWED,
            Self::Internal(e) => {
                eprintln!("internal error: {e:#}");
                StatusCode::INTERNAL_SERVER_ERROR
            }
        };
        (status, Json(json!({ "error": self.to_string() }))).into_response()
    }
}

type ApiResult<T> = Result<T, ApiError>;

/// Runs a blocking database operation off the async executor.
async fn with_store<T, F>(store: AppState, op: F) -> ApiResult<T>
where
    T: Send + 'static,
    F: FnOnce(&Store) -> rusqlite::Result<T> + Send + 'static,
{
    tokio::task::spawn_blocking(move || op(&store))
        .await
        .map_err(|e| ApiError::Internal(e.into()))?
        .map_err(ApiError::from)
}

/// Parses a note id path segment; anything but a positive integer is a 404.
fn parse_id(raw: &str) -> ApiResult<i64> {
    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
        return Err(ApiError::NotFound);
    }
    match raw.parse::<i64>() {
        Ok(id) if id > 0 => Ok(id),
        _ => Err(ApiError::NotFound),
    }
}

fn parse_list_query(raw: Option<&str>) -> ApiResult<ListFilter> {
    let mut filter = ListFilter::default();
    for (key, value) in form_urlencoded::parse(raw.unwrap_or_default().as_bytes()) {
        match &*key {
            "tag" => filter.tag = Some(value.into_owned()),
            "q" => filter.q = Some(value.into_owned()),
            "after" => {
                filter.after = value
                    .parse()
                    .map_err(|_| ApiError::BadQuery("after must be an integer"))?;
            }
            "limit" => {
                filter.limit = value
                    .parse()
                    .ok()
                    .filter(|n| (1..=MAX_LIMIT).contains(n))
                    .ok_or(ApiError::BadQuery("limit must be an integer from 1 to 100"))?;
            }
            _ => {}
        }
    }
    Ok(filter)
}

async fn health() -> &'static str {
    "ok"
}

async fn not_found() -> ApiError {
    ApiError::NotFound
}

async fn method_not_allowed() -> ApiError {
    ApiError::MethodNotAllowed
}

async fn create_note(State(store): State<AppState>, body: Bytes) -> ApiResult<impl IntoResponse> {
    let input = NoteInput::from_json(&body)?;
    let note = with_store(store, move |s| s.create(&input)).await?;
    Ok((StatusCode::CREATED, Json(note)))
}

async fn get_note(State(store): State<AppState>, Path(id): Path<String>) -> ApiResult<Json<Note>> {
    let id = parse_id(&id)?;
    with_store(store, move |s| s.get(id))
        .await?
        .map(Json)
        .ok_or(ApiError::NotFound)
}

async fn update_note(
    State(store): State<AppState>,
    Path(id): Path<String>,
    body: Bytes,
) -> ApiResult<Json<Note>> {
    let id = parse_id(&id)?;
    let input = NoteInput::from_json(&body)?;
    with_store(store, move |s| s.update(id, &input))
        .await?
        .map(Json)
        .ok_or(ApiError::NotFound)
}

async fn delete_note(State(store): State<AppState>, Path(id): Path<String>) -> ApiResult<StatusCode> {
    let id = parse_id(&id)?;
    if with_store(store, move |s| s.delete(id)).await? {
        Ok(StatusCode::NO_CONTENT)
    } else {
        Err(ApiError::NotFound)
    }
}

async fn list_notes(State(store): State<AppState>, RawQuery(query): RawQuery) -> ApiResult<Json<Value>> {
    let filter = parse_list_query(query.as_deref())?;
    let notes = with_store(store, move |s| s.list(&filter)).await?;
    Ok(Json(json!({ "notes": notes })))
}

async fn stats(State(store): State<AppState>) -> ApiResult<Json<Value>> {
    let (count, tags) = with_store(store, |s| Ok((s.count()?, s.tag_counts()?))).await?;
    let tags: Map<String, Value> = tags.into_iter().map(|(t, n)| (t, n.into())).collect();
    Ok(Json(json!({ "notes": count, "tags": tags })))
}

async fn tags(State(store): State<AppState>) -> ApiResult<Json<Value>> {
    let tags = with_store(store, |s| s.tag_counts()).await?;
    let tags: Vec<Value> = tags
        .into_iter()
        .map(|(tag, count)| json!({ "tag": tag, "count": count }))
        .collect();
    Ok(Json(json!({ "tags": tags })))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids() {
        assert_eq!(parse_id("12").unwrap(), 12);
        for bad in ["0", "-1", "+1", "abc", "", "1.0", "99999999999999999999"] {
            assert!(matches!(parse_id(bad), Err(ApiError::NotFound)), "{bad}");
        }
    }

    #[test]
    fn list_query() {
        let f = parse_list_query(Some("tag=a&q=Hi+there&after=3&limit=5&x=1")).unwrap();
        assert_eq!(f.tag.as_deref(), Some("a"));
        assert_eq!(f.q.as_deref(), Some("Hi there"));
        assert_eq!((f.after, f.limit), (3, 5));
        assert_eq!(parse_list_query(None).unwrap(), ListFilter::default());
        for bad in ["limit=0", "limit=101", "limit=", "limit=x", "after=x", "after=1.5"] {
            assert!(parse_list_query(Some(bad)).is_err(), "{bad}");
        }
    }
}

//! SQLite-backed note storage.

use std::path::Path;
use std::sync::{Mutex, MutexGuard};

use rusqlite::{Connection, OptionalExtension, Transaction, params};

use crate::model::{Note, NoteInput};

const SCHEMA: &str = "
    CREATE TABLE IF NOT EXISTS notes (
        id    INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        body  TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS note_tags (
        note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
        tag     TEXT NOT NULL,
        PRIMARY KEY (note_id, tag)
    ) WITHOUT ROWID;
    CREATE INDEX IF NOT EXISTS note_tags_by_tag ON note_tags(tag, note_id);
";

/// Filters for listing notes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ListFilter {
    pub tag: Option<String>,
    pub q: Option<String>,
    pub after: i64,
    pub limit: usize,
}

impl Default for ListFilter {
    fn default() -> Self {
        Self {
            tag: None,
            q: None,
            after: i64::MIN,
            limit: 100,
        }
    }
}

/// Thread-safe handle to the notes database.
///
/// A single connection serialises all access, which keeps id assignment and
/// multi-statement updates trivially consistent.
pub struct Store {
    conn: Mutex<Connection>,
}

impl Store {
    /// Opens (creating if needed) the database at `path` and ensures the schema exists.
    pub fn open(path: impl AsRef<Path>) -> rusqlite::Result<Self> {
        Self::init(Connection::open(path)?)
    }

    #[cfg(test)]
    pub fn open_in_memory() -> rusqlite::Result<Self> {
        Self::init(Connection::open_in_memory()?)
    }

    fn init(conn: Connection) -> rusqlite::Result<Self> {
        conn.pragma_update(None, "journal_mode", "WAL")?;
        conn.pragma_update(None, "synchronous", "NORMAL")?;
        conn.pragma_update(None, "foreign_keys", true)?;
        conn.execute_batch(SCHEMA)?;
        Ok(Self {
            conn: Mutex::new(conn),
        })
    }

    fn conn(&self) -> MutexGuard<'_, Connection> {
        // A panic while holding the lock cannot leave SQLite in a torn state
        // (transactions roll back on drop), so recovering from poison is safe.
        self.conn.lock().unwrap_or_else(|e| e.into_inner())
    }

    pub fn create(&self, input: &NoteInput) -> rusqlite::Result<Note> {
        let mut conn = self.conn();
        let tx = conn.transaction()?;
        tx.execute(
            "INSERT INTO notes (title, body) VALUES (?1, ?2)",
            params![input.title, input.body],
        )?;
        let id = tx.last_insert_rowid();
        insert_tags(&tx, id, &input.tags)?;
        tx.commit()?;
        Ok(note_from_input(id, input))
    }

    pub fn get(&self, id: i64) -> rusqlite::Result<Option<Note>> {
        let conn = self.conn();
        let row = conn
            .query_row(
                "SELECT title, body FROM notes WHERE id = ?1",
                [id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()?;
        row.map(|(title, body)| {
            Ok(Note {
                id,
                title,
                body,
                tags: load_tags(&conn, id)?,
            })
        })
        .transpose()
    }

    /// Replaces a note's contents; returns `None` if it does not exist.
    pub fn update(&self, id: i64, input: &NoteInput) -> rusqlite::Result<Option<Note>> {
        let mut conn = self.conn();
        let tx = conn.transaction()?;
        let changed = tx.execute(
            "UPDATE notes SET title = ?1, body = ?2 WHERE id = ?3",
            params![input.title, input.body, id],
        )?;
        if changed == 0 {
            return Ok(None);
        }
        tx.execute("DELETE FROM note_tags WHERE note_id = ?1", [id])?;
        insert_tags(&tx, id, &input.tags)?;
        tx.commit()?;
        Ok(Some(note_from_input(id, input)))
    }

    /// Deletes a note; returns whether it existed.
    pub fn delete(&self, id: i64) -> rusqlite::Result<bool> {
        let conn = self.conn();
        Ok(conn.execute("DELETE FROM notes WHERE id = ?1", [id])? > 0)
    }

    /// Lists notes matching `filter`, ordered by id ascending.
    pub fn list(&self, filter: &ListFilter) -> rusqlite::Result<Vec<Note>> {
        let conn = self.conn();
        let mut stmt = conn.prepare_cached(
            "SELECT id, title, body FROM notes
             WHERE id > ?1
               AND (?2 IS NULL OR EXISTS (
                    SELECT 1 FROM note_tags t WHERE t.note_id = notes.id AND t.tag = ?2))
             ORDER BY id",
        )?;
        let mut rows = stmt.query(params![filter.after, filter.tag])?;
        let mut notes = Vec::new();
        while notes.len() < filter.limit {
            let Some(row) = rows.next()? else { break };
            let title: String = row.get(1)?;
            let body: String = row.get(2)?;
            if let Some(q) = &filter.q
                && !contains_ignore_ascii_case(&title, q)
                && !contains_ignore_ascii_case(&body, q)
            {
                continue;
            }
            let id = row.get(0)?;
            notes.push(Note {
                id,
                title,
                body,
                tags: load_tags(&conn, id)?,
            });
        }
        Ok(notes)
    }

    /// Total number of notes.
    pub fn count(&self) -> rusqlite::Result<i64> {
        self.conn()
            .query_row("SELECT COUNT(*) FROM notes", [], |row| row.get(0))
    }

    /// Every tag in use with the number of notes carrying it, ordered by
    /// count descending, then tag ascending.
    pub fn tag_counts(&self) -> rusqlite::Result<Vec<(String, i64)>> {
        let conn = self.conn();
        let mut stmt = conn.prepare_cached(
            "SELECT tag, COUNT(*) AS n FROM note_tags GROUP BY tag ORDER BY n DESC, tag ASC",
        )?;
        stmt.query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?
            .collect()
    }
}

fn note_from_input(id: i64, input: &NoteInput) -> Note {
    Note {
        id,
        title: input.title.clone(),
        body: input.body.clone(),
        tags: input.tags.clone(),
    }
}

fn insert_tags(tx: &Transaction<'_>, id: i64, tags: &[String]) -> rusqlite::Result<()> {
    let mut stmt = tx.prepare_cached("INSERT INTO note_tags (note_id, tag) VALUES (?1, ?2)")?;
    for tag in tags {
        stmt.execute(params![id, tag])?;
    }
    Ok(())
}

fn load_tags(conn: &Connection, id: i64) -> rusqlite::Result<Vec<String>> {
    let mut stmt = conn.prepare_cached("SELECT tag FROM note_tags WHERE note_id = ?1 ORDER BY tag")?;
    stmt.query_map([id], |row| row.get(0))?.collect()
}

/// Whether `haystack` contains `needle`, comparing ASCII letters case-insensitively.
fn contains_ignore_ascii_case(haystack: &str, needle: &str) -> bool {
    let (h, n) = (haystack.as_bytes(), needle.as_bytes());
    n.is_empty() || h.windows(n.len()).any(|w| w.eq_ignore_ascii_case(n))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn input(title: &str, body: &str, tags: &[&str]) -> NoteInput {
        NoteInput {
            title: title.into(),
            body: body.into(),
            tags: tags.iter().map(|t| t.to_string()).collect(),
        }
    }

    #[test]
    fn ids_are_never_reused() {
        let store = Store::open_in_memory().unwrap();
        assert_eq!(store.create(&input("a", "", &[])).unwrap().id, 1);
        assert_eq!(store.create(&input("b", "", &[])).unwrap().id, 2);
        assert!(store.delete(2).unwrap());
        assert!(!store.delete(2).unwrap());
        assert_eq!(store.create(&input("c", "", &[])).unwrap().id, 3);
    }

    #[test]
    fn persists_across_reopen() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("notes.db");
        {
            let store = Store::open(&path).unwrap();
            store.create(&input("a", "x", &["t"])).unwrap();
            store.create(&input("b", "", &[])).unwrap();
            store.delete(2).unwrap();
        }
        let store = Store::open(&path).unwrap();
        assert_eq!(store.get(1).unwrap().unwrap().tags, ["t"]);
        assert_eq!(store.create(&input("c", "", &[])).unwrap().id, 3);
    }

    #[test]
    fn update_replaces_tags() {
        let store = Store::open_in_memory().unwrap();
        store.create(&input("a", "x", &["old"])).unwrap();
        let note = store.update(1, &input("b", "", &["new"])).unwrap().unwrap();
        assert_eq!(store.get(1).unwrap().unwrap(), note);
        assert_eq!(store.tag_counts().unwrap(), [("new".to_string(), 1)]);
        assert!(store.update(9, &input("b", "", &[])).unwrap().is_none());
    }

    #[test]
    fn list_filters() {
        let store = Store::open_in_memory().unwrap();
        store.create(&input("Hello", "", &["g"])).unwrap();
        store.create(&input("other", "say HELLO", &["g", "m"])).unwrap();
        store.create(&input("none", "", &[])).unwrap();
        let ids = |f: ListFilter| -> Vec<i64> {
            store.list(&f).unwrap().iter().map(|n| n.id).collect()
        };
        assert_eq!(ids(ListFilter::default()), [1, 2, 3]);
        let q = Some("hello".to_string());
        assert_eq!(ids(ListFilter { q: q.clone(), ..Default::default() }), [1, 2]);
        let tag = Some("m".to_string());
        assert_eq!(ids(ListFilter { tag, q, ..Default::default() }), [2]);
        assert_eq!(ids(ListFilter { after: 1, limit: 1, ..Default::default() }), [2]);
    }

    #[test]
    fn tag_counts_ignore_deleted_notes() {
        let store = Store::open_in_memory().unwrap();
        store.create(&input("a", "", &["x", "y"])).unwrap();
        store.create(&input("b", "", &["y"])).unwrap();
        store.create(&input("c", "", &["z"])).unwrap();
        store.delete(3).unwrap();
        assert_eq!(
            store.tag_counts().unwrap(),
            [("y".to_string(), 2), ("x".to_string(), 1)]
        );
        assert_eq!(store.count().unwrap(), 2);
    }

    #[test]
    fn ascii_case_insensitive_contains() {
        assert!(contains_ignore_ascii_case("Say HELLO", "hello"));
        assert!(contains_ignore_ascii_case("abc", ""));
        assert!(!contains_ignore_ascii_case("ÉCOLE", "école"));
    }
}

//! A small notes store over HTTP, backed by SQLite.
//!
//! Usage: `NOTES_DB=/path/to/notes.db app <port>`

mod api;
mod db;
mod model;

use std::net::{Ipv4Addr, SocketAddr};
use std::sync::Arc;

use anyhow::{Context, bail};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let mut args = std::env::args().skip(1);
    let (Some(port), None) = (args.next(), args.next()) else {
        bail!("usage: app <port>");
    };
    let port: u16 = port.parse().with_context(|| format!("invalid port {port:?}"))?;
    let db_path = std::env::var_os("NOTES_DB").context("NOTES_DB must be set")?;

    let store = db::Store::open(&db_path)
        .with_context(|| format!("opening database {}", db_path.to_string_lossy()))?;

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .with_context(|| format!("binding {addr}"))?;
    axum::serve(listener, api::router(Arc::new(store)))
        .await
        .context("serving HTTP")
}

//! Note types and input validation.

use serde::Serialize;
use serde_json::Value;

pub const MAX_TITLE_CHARS: usize = 200;
pub const MAX_TAG_CHARS: usize = 32;

/// A stored note.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Note {
    pub id: i64,
    pub title: String,
    pub body: String,
    pub tags: Vec<String>,
}

/// Validated contents of a note, as supplied by a create or update request.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NoteInput {
    pub title: String,
    pub body: String,
    pub tags: Vec<String>,
}

/// Why a request body was rejected.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum ValidationError {
    #[error("request body is not valid JSON")]
    InvalidJson,
    #[error("request body must be a JSON object")]
    NotAnObject,
    #[error("title is required")]
    MissingTitle,
    #[error("title must be a string")]
    TitleNotString,
    #[error("title must be 1-{MAX_TITLE_CHARS} characters")]
    TitleLength,
    #[error("body must be a string")]
    BodyNotString,
    #[error("tags must be an array of strings")]
    TagsNotArray,
    #[error("each tag must be 1-{MAX_TAG_CHARS} characters from a-z, 0-9 and -")]
    InvalidTag,
}

impl NoteInput {
    /// Parses and validates a raw JSON request body.
    pub fn from_json(bytes: &[u8]) -> Result<Self, ValidationError> {
        let value: Value =
            serde_json::from_slice(bytes).map_err(|_| ValidationError::InvalidJson)?;
        let Value::Object(mut obj) = value else {
            return Err(ValidationError::NotAnObject);
        };

        let title = match obj.remove("title") {
            None => return Err(ValidationError::MissingTitle),
            Some(Value::String(s)) => normalize_title(&s)?,
            Some(_) => return Err(ValidationError::TitleNotString),
        };

        let body = match obj.remove("body") {
            None => String::new(),
            Some(Value::String(s)) => s,
            Some(_) => return Err(ValidationError::BodyNotString),
        };

        let tags = match obj.remove("tags") {
            None => Vec::new(),
            Some(Value::Array(items)) => normalize_tags(items)?,
            Some(_) => return Err(ValidationError::TagsNotArray),
        };

        Ok(Self { title, body, tags })
    }
}

fn normalize_title(raw: &str) -> Result<String, ValidationError> {
    let title = raw.trim();
    let len = title.chars().count();
    if (1..=MAX_TITLE_CHARS).contains(&len) {
        Ok(title.to_owned())
    } else {
        Err(ValidationError::TitleLength)
    }
}

fn normalize_tags(items: Vec<Value>) -> Result<Vec<String>, ValidationError> {
    let mut tags = items
        .into_iter()
        .map(|item| match item {
            Value::String(tag) if is_valid_tag(&tag) => Ok(tag),
            Value::String(_) => Err(ValidationError::InvalidTag),
            _ => Err(ValidationError::TagsNotArray),
        })
        .collect::<Result<Vec<_>, _>>()?;
    tags.sort_unstable();
    tags.dedup();
    Ok(tags)
}

/// Whether `tag` is 1-32 characters from `a-z`, `0-9` and `-`.
pub fn is_valid_tag(tag: &str) -> bool {
    (1..=MAX_TAG_CHARS).contains(&tag.len())
        && tag
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(s: &str) -> Result<NoteInput, ValidationError> {
        NoteInput::from_json(s.as_bytes())
    }

    #[test]
    fn defaults_and_normalization() {
        let n = parse(r#"{"title":"  hi  ","tags":["b","a","b"]}"#).unwrap();
        assert_eq!(n.title, "hi");
        assert_eq!(n.body, "");
        assert_eq!(n.tags, ["a", "b"]);
    }

    #[test]
    fn rejects_bad_shapes() {
        assert_eq!(parse("{"), Err(ValidationError::InvalidJson));
        assert_eq!(parse("[]"), Err(ValidationError::NotAnObject));
        assert_eq!(parse("{}"), Err(ValidationError::MissingTitle));
        assert_eq!(parse(r#"{"title":1}"#), Err(ValidationError::TitleNotString));
        assert_eq!(parse(r#"{"title":"   "}"#), Err(ValidationError::TitleLength));
        assert_eq!(parse(r#"{"title":"x","body":null}"#), Err(ValidationError::BodyNotString));
        assert_eq!(parse(r#"{"title":"x","tags":"a"}"#), Err(ValidationError::TagsNotArray));
        assert_eq!(parse(r#"{"title":"x","tags":[1]}"#), Err(ValidationError::TagsNotArray));
        assert_eq!(parse(r#"{"title":"x","tags":["Bad"]}"#), Err(ValidationError::InvalidTag));
        assert_eq!(parse(r#"{"title":"x","tags":[""]}"#), Err(ValidationError::InvalidTag));
    }

    #[test]
    fn title_length_counts_characters() {
        let ok = format!(r#"{{"title":"{}"}}"#, "é".repeat(200));
        assert!(parse(&ok).is_ok());
        let long = format!(r#"{{"title":"{}"}}"#, "a".repeat(201));
        assert_eq!(parse(&long), Err(ValidationError::TitleLength));
    }

    #[test]
    fn tag_rules() {
        assert!(is_valid_tag("a-1"));
        assert!(is_valid_tag(&"a".repeat(32)));
        assert!(!is_valid_tag(&"a".repeat(33)));
        assert!(!is_valid_tag("a_b"));
        assert!(!is_valid_tag("é"));
    }
